import React from 'react';
import { Box, Container } from '@mui/material';
import Slider from 'react-slick';
import "slick-carousel/slick/slick.css"; 
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
  };

  const slides = [
    { image: './assets/images/banner1.webp', link: 'https://www.techcareer.net/courses' },
    { image: './assets/images/banner2.webp', link: 'https://www.techcareer.net/jobs' },
    { image: './assets/images/banner3.webp', link: 'https://www.techcareer.net/blog' },
  ];

  return (
    <Box className="background-container" sx={{ width: '100%' }}>
      <Box className="background-dots" />
      <Box className="background-lines" />
      <Container 
        sx={{ 
          height: '600px',
          padding: '40px',
          position: 'relative',
          zIndex: 1
        }}
      >
        <Slider {...settings}>
          {slides.map((slide, index) => (
            <Box key={index}>
              <Box sx={{ height: '500px' }}>
                <a href={slide.link}>
                  <img
                    src={slide.image}
                    alt={`Banner ${index + 1}`}
                    className="shadow-green"
                    style={{
                      width: '100%',
                      height: '429px',
                      display: 'flex',
                      objectFit: 'cover'
                    }}
                  />
                </a>
              </Box>
            </Box>
          ))}
        </Slider>
      </Container>
      <Box className="background-tape" />
    </Box>
  );
};

export default EventsSlider;
